# This Day in History API
import requests

HISTORY_API_KEY = "088440d910mshef857391f2fc461p17ae9ejsnaebc918926ff"
BASE_URL = "https://history.muffinlabs.com"

def get_todays_events():
    """Get historical events that happened today"""
    response = requests.get(f"{BASE_URL}/date")
    return response.json()

def get_date_events(month, day):
    """Get historical events for a specific date"""
    response = requests.get(f"{BASE_URL}/date/{month}/{day}")
    return response.json()

def get_births_on_date(month, day):
    """Get notable births on a specific date"""
    data = get_date_events(month, day)
    return data.get('data', {}).get('Births', [])

def get_deaths_on_date(month, day):
    """Get notable deaths on a specific date"""
    data = get_date_events(month, day)
    return data.get('data', {}).get('Deaths', [])
